def protect_evidence(apps, schema_editor):
    tables = ('service_originalityattestation', 'service_prescreenresult', 'service_rightsevent', 'service_sourcedigest', 'service_screeningrecord')
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("CREATE OR REPLACE FUNCTION copyright_evidence_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'copyright evidence is append-only'; END $$")
        for table in tables:
            schema_editor.execute(f"CREATE TRIGGER copyright_no_mutation BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION copyright_evidence_immutable()")
            schema_editor.execute(f"CREATE TRIGGER copyright_no_truncate BEFORE TRUNCATE ON {table} FOR EACH STATEMENT EXECUTE FUNCTION copyright_evidence_immutable()")
    elif schema_editor.connection.vendor == "sqlite":
        for table in tables:
            for action in ("UPDATE", "DELETE"):
                schema_editor.execute(f"CREATE TRIGGER {table}_immutable_{action.lower()} BEFORE {action} ON {table} BEGIN SELECT RAISE(ABORT, 'copyright evidence is append-only'); END")
    else:
        raise RuntimeError("Copyright evidence requires PostgreSQL or fixture SQLite")


def normalize_legacy_rights(apps, schema_editor):
    # Prior screening's attested label did not record per-upload creator consent.
    apps.get_model("service", "Video").objects.filter(rights_status__in=["not_recorded", "muted", "hidden", "attested"]).update(rights_status="flagged")


